<!DOCTYPE html>
<html lang="pl">
<head>
</head>
<body>
<style>
    @import url(//fonts.googleapis.com/css?family=Montserrat:100);img:is([sizes=auto i],[sizes^="auto," i]) {
    contain-intrinsic-size: 3000px 1500px
}

:root {
    --wp-block-synced-color: #7a00df;
    --wp-block-synced-color--rgb: 122,0,223;
    --wp-bound-block-color: var(--wp-block-synced-color);
    --wp-editor-canvas-background: #ddd;
    --wp-admin-theme-color: #007cba;
    --wp-admin-theme-color--rgb: 0,124,186;
    --wp-admin-theme-color-darker-10: #006ba1;
    --wp-admin-theme-color-darker-10--rgb: 0,107,160.5;
    --wp-admin-theme-color-darker-20: #005a87;
    --wp-admin-theme-color-darker-20--rgb: 0,90,135;
    --wp-admin-border-width-focus: 2px
}

@media (min-resolution: 192dpi) {
    :root {
        --wp-admin-border-width-focus:1.5px
    }
}

.wp-element-button {
    cursor: pointer
}

:root .has-very-light-gray-background-color {
    background-color: #eee
}

:root .has-very-dark-gray-background-color {
    background-color: #313131
}

:root .has-very-light-gray-color {
    color: #eee
}

:root .has-very-dark-gray-color {
    color: #313131
}

:root .has-vivid-green-cyan-to-vivid-cyan-blue-gradient-background {
    background: linear-gradient(135deg,#00d084,#0693e3)
}

:root .has-purple-crush-gradient-background {
    background: linear-gradient(135deg,#34e2e4,#4721fb 50%,#ab1dfe)
}

:root .has-hazy-dawn-gradient-background {
    background: linear-gradient(135deg,#faaca8,#dad0ec)
}

:root .has-subdued-olive-gradient-background {
    background: linear-gradient(135deg,#fafae1,#67a671)
}

:root .has-atomic-cream-gradient-background {
    background: linear-gradient(135deg,#fdd79a,#004a59)
}

:root .has-nightshade-gradient-background {
    background: linear-gradient(135deg,#330968,#31cdcf)
}

:root .has-midnight-gradient-background {
    background: linear-gradient(135deg,#020381,#2874fc)
}

:root {
    --wp--preset--font-size--normal: 16px;
    --wp--preset--font-size--huge: 42px
}

.has-regular-font-size {
    font-size: 1em
}

.has-larger-font-size {
    font-size: 2.625em
}

.has-normal-font-size {
    font-size: var(--wp--preset--font-size--normal)
}

.has-huge-font-size {
    font-size: var(--wp--preset--font-size--huge)
}

:root .has-text-align-center {
    text-align: center
}

:root .has-text-align-left {
    text-align: left
}

:root .has-text-align-right {
    text-align: right
}

.has-fit-text {
    white-space: nowrap!important
}

#end-resizable-editor-section {
    display: none
}

.aligncenter {
    clear: both
}

.items-justified-left {
    justify-content: flex-start
}

.items-justified-center {
    justify-content: center
}

.items-justified-right {
    justify-content: flex-end
}

.items-justified-space-between {
    justify-content: space-between
}

.screen-reader-text {
    word-wrap: normal!important;
    border: 0;
    clip-path: inset(50%);
    height: 1px;
    margin: -1px;
    overflow: hidden;
    padding: 0;
    position: absolute;
    width: 1px
}

.screen-reader-text:focus {
    background-color: #ddd;
    clip-path: none;
    color: #444;
    display: block;
    font-size: 1em;
    height: auto;
    left: 5px;
    line-height: normal;
    padding: 15px 23px 14px;
    text-decoration: none;
    top: 5px;
    width: auto;
    z-index: 100000
}

html :where(.has-border-color) {
    border-style: solid
}

html :where([style*=border-color]) {
    border-style: solid
}

html :where([style*=border-top-color]) {
    border-top-style: solid
}

html :where([style*=border-right-color]) {
    border-right-style: solid
}

html :where([style*=border-bottom-color]) {
    border-bottom-style: solid
}

html :where([style*=border-left-color]) {
    border-left-style: solid
}

html :where([style*=border-width]) {
    border-style: solid
}

html :where([style*=border-top-width]) {
    border-top-style: solid
}

html :where([style*=border-right-width]) {
    border-right-style: solid
}

html :where([style*=border-bottom-width]) {
    border-bottom-style: solid
}

html :where([style*=border-left-width]) {
    border-left-style: solid
}

html :where(img[class*=wp-image-]) {
    height: auto;
    max-width: 100%
}

:where(figure) {
    margin: 0 0 1em
}

html :where(.is-position-sticky) {
    --wp-admin--admin-bar--position-offset: var(--wp-admin--admin-bar--height,0px)
}

@media screen and (max-width: 600px) {
    html :where(.is-position-sticky) {
        --wp-admin--admin-bar--position-offset:0px
    }
}

.components-placeholder.ms-loader {
    position: absolute;
    width: 100%;
    height: 100%;
    z-index: 3;
    top: 0;
    left: 0;
    background: rgb(243 243 244 / .83);
    min-height: 50px
}

.wp-block-metaslider-slider iframe {
    transition: height .6s;
    width: 100%
}

.ms-preview {
    position: relative
}

.ms-preview__trigger {
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0
}

.components-base-control.ms-loading .is-active.spinner {
    margin-top: -2px;
    float: none;
    margin-left: 0
}

.ms-plugin-link {
    display: block;
    padding: 15px;
    border-top: 1px solid #e2e4e7;
    border-bottom: 1px solid #e2e4e7;
    margin-left: -16px;
    margin-right: -16px;
    margin-top: 17px
}

.ms-edit-current-slideshow {
    position: relative;
    float: right;
    margin-top: -11px;
    font-size: .95em
}

.ms-edit-current-slideshow::before {
    content: "\f474";
    font-family: dashicons;
    position: absolute;
    left: -19px;
    transform: rotate(90deg);
    color: #ccc;
    font-size: 1.2em
}

.wp-block-metaslider-slider.placeholder-loading+.wp-block-metaslider-slider {
    display: none
}

.wp-block-metaslider-slider {
    transition: height .3s
}

p.cr-comment-image-text {
    margin-bottom: .5em;
    font-size: .9em
}

p.cr-comment-video-text {
    margin-bottom: .5em;
    font-size: .9em
}

.iv-comment-image {
    float: left;
    margin-right: 5px;
    margin-left: 0;
    margin-bottom: 5px;
    margin-top: 0;
    border-radius: 5px;
    overflow: hidden;
    border: 1px solid #e4e1e3;
    filter: brightness(100%)
}

.iv-comment-image:hover,.cr-comment-video:hover {
    filter: brightness(95%)
}

.cr-comment-image-top {
    display: inline-block;
    margin-right: 5px;
    vertical-align: top;
    max-height: 150px;
    border-radius: 5px;
    overflow: hidden;
    border: 1px solid #e4e1e3;
    filter: brightness(100%);
    box-sizing: content-box;
    position: relative
}

.cr-comment-image-top:hover {
    filter: brightness(95%)
}

.cr-comment-video {
    float: left;
    margin-right: 5px;
    margin-bottom: 5px;
    position: relative;
    cursor: pointer;
    border-radius: 5px;
    overflow: hidden;
    border: 1px solid #e4e1e3;
    filter: brightness(100%)
}

.cr-comment-video video.cr-video-a {
    width: 75px;
    height: 75px;
    display: block;
    object-fit: cover
}

.cr-comment-video-modal.cr-comment-video video.cr-video-a {
    width: auto;
    height: auto;
    max-width: 100%;
    max-height: 100%;
    object-fit: contain;
    background-color: rgb(0 0 0 / .4)
}

.cr-comment-video .cr-comment-videoicon,.cr-comment-image-top .cr-comment-videoicon {
    position: absolute;
    top: 50%;
    left: 50%;
    width: 32px;
    height: auto;
    margin-top: -16px;
    margin-left: -16px
}

#reviews.cr-reviews-ajax-reviews .cr-ajax-reviews-cus-images-modal .cr-ajax-reviews-cus-images-slider-nav .cr-ajax-reviews-slide-nav .cr-comment-videoicon,.cr-all-reviews-shortcode .cr-ajax-reviews-cus-images-modal .cr-ajax-reviews-cus-images-slider-nav .cr-ajax-reviews-slide-nav .cr-comment-videoicon {
    position: absolute;
    top: 50%;
    left: 50%;
    width: 26px;
    height: auto;
    margin-top: -13px;
    margin-left: -13px
}

.cr-comment-image-top img,.cr-comment-image-top video {
    width: 150px;
    height: 150px;
    box-shadow: none;
    padding: 0;
    border-radius: 0;
    object-fit: cover;
    cursor: pointer
}

#reviews div.iv-comment-image img,div.iv-comment-image img {
    box-shadow: none;
    width: 75px;
    height: 75px;
    max-width: 75px;
    max-height: 75px;
    object-fit: cover;
    padding: 0;
    border-radius: 0;
    display: block;
    position: relative
}

.cr-comment-images,.cr-comment-videos {
    margin-bottom: 1em
}

.cr-all-reviews-shortcode .cr-comment-images,.cr-comment-videos {
    margin: 0
}

.cr-all-reviews-shortcode .comment_container .avatar,.cr-ajax-reviews-list .comment_container .avatar {
