.sr-only {
    clip: rect(0,0,0,0);
    border: 0;
    height: 1px;
    margin: -1px;
    overflow: hidden;
    padding: 0;
    position: absolute;
    width: 1px
}

.sr-only-focusable:active,.sr-only-focusable:focus {
    clip: auto;
    height: auto;
    margin: 0;
    overflow: visible;
    position: static;
    width: auto
}

#proof {
    background: #fff;
    border: none;
    display: none;
    height: 66px;
    opacity: 0;
    position: fixed;
    transition: visibility 0s .5s,opacity .4s linear,top .5s linear,bottom .5s linear;
    width: 358px;
    z-index: 99999
}

#proof,#proof *,#proof :after,#proof :before {
    box-sizing: border-box
}

#proof.proof-clickable {
    cursor: pointer
}

#proof.proof-position-bottom-left {
    left: 10px
}

#proof.proof-position-bottom-left,#proof.proof-position-bottom-right {
    bottom: -120px;
    box-shadow: 0 0 1px rgb(0 0 0 / .2),0 1px 2px rgb(0 0 0 / .05),0 8px 50px rgb(0 0 0 / .05)
}

#proof.proof-position-bottom-right {
    right: 10px
}

#proof.proof-position-top-left {
    left: 10px
}

#proof.proof-position-top-left,#proof.proof-position-top-right {
    box-shadow: 0 0 1px rgb(0 0 0 / .2),0 -1px 2px rgb(0 0 0 / .05),0 -8px 50px rgb(0 0 0 / .05);
    top: -120px
}

#proof.proof-position-top-right {
    right: 10px
}

#proof.proof-design-rounded {
    border-radius: 40px
}

#proof.proof-design-rounded-square {
    border-radius: 6px
}

#proof.proof-position-bottom-left:hover,#proof.proof-position-bottom-right:hover {
    box-shadow: 0 0 1px rgb(0 0 0 / .2),0 1px 2px rgb(0 0 0 / .05),0 25px 50px rgb(0 0 0 / .1)
}

#proof.proof-position-top-left:hover,#proof.proof-position-top-right:hover {
    box-shadow: 0 0 1px rgb(0 0 0 / .2),0 -1px 2px rgb(0 0 0 / .05),0 -25px 50px rgb(0 0 0 / .1)
}

#proof:hover {
    box-shadow: 0 25px 50px rgb(0 0 0 / .1)
}

#proof:active {
    box-shadow: 0 0 0 1px rgb(0 0 0 / .1)
}

#proof.proof-hidden {
    opacity: 0
}

#proof.proof-displayed.proof-position-bottom-left,#proof.proof-displayed.proof-position-bottom-right {
    bottom: 20px;
    opacity: 1
}

#proof.proof-displayed.proof-position-top-left,#proof.proof-displayed.proof-position-top-right {
    opacity: 1;
    top: 20px
}

#proof-image {
    background-position: 50%;
    background-repeat: no-repeat;
    background-size: cover;
    display: block;
    height: 66px;
    left: 0;
    position: absolute;
    text-align: center;
    top: 0;
    width: 66px
}

#proof-image i {
    font-size: 30px;
    height: 66px;
    line-height: 66px;
    margin: 0;
    max-width: 100%;
    width: 66px
}

#proof.proof-design-rounded #proof-image {
    overflow: hidden
}

#proof.proof-design-rounded #proof-image,#proof.proof-design-rounded #proof-image i {
    border-bottom-left-radius: 50%;
    border-bottom-right-radius: 50%;
    border-top-left-radius: 50%;
    border-top-right-radius: 50%;
    height: 60px;
    left: 3px;
    line-height: 60px;
    top: 3px;
    width: 60px
}

#proof.proof-design-rounded #proof-image i {
    display: block
}

#proof-content {
    margin-left: 75px;
    padding-right: 4px;
    padding-top: 9.28571px
}

#proof-title {
    color: #000;
    font-size: 14px;
    font-weight: 700;
    height: 18px;
    line-height: 18px;
    margin-right: 30px;
    margin-top: 7px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap
}

#proof.proof-show-timeago #proof-title {
    margin-top: 0
}

#proof-text {
    color: #333;
    font-size: 11px;
    height: 17px;
    line-height: 17px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap
}

.proof-design-rounded_square #proof-content {
    padding-left: 10px
}

.proof-design-rounded_square #proof-close {
    right: 15px
}

#proof-optimizecheckouts-verified,#proof-optimizepress-verified,#proof-wc-verified {
    color: #999;
    display: inline-block;
    font-size: 11px;
    height: 14px;
    height: 17px;
    line-height: 17px;
    margin-left: 15px;
    vertical-align: top
}

.optimizecheckouts_verified-icon,.optimizepress_verified-icon,.wc_verified-icon {
    color: #00ce0a;
    padding-right: 3px
}

#proof-time {
    color: #999;
    display: inline-block;
    font-size: 11px;
    height: 17px;
    line-height: 17px;
    vertical-align: top
}

#proof-close {
    color: #000;
    cursor: pointer;
    font-size: 12px;
    position: absolute;
    right: 25px;
    top: 3px
}

.visitors-count-text {
    font-size: 14px
}

#visitor-text {
    font-size: 15px;
    padding-top: 13px
}

.visitors-count {
    color: #264bc7;
    font-weight: 600
}

@media (min-width: 980px) {
    #proof.proof-desktop {
        display:block
    }
}

@media (max-width: 979px) {
    #proof.proof-mobile {
        display:block
    }
}

@keyframes proofAnimationBottom {
    0% {
        transform: matrix(1,0,0,1,0,300)
    }

    4.1% {
        transform: matrix(1,0,0,1,0,125.912)
    }

    8.11% {
        transform: matrix(1,0,0,1,0,31.647)
    }

    12.11% {
        transform: matrix(1,0,0,1,0,-5.53)
    }

    16.12% {
        transform: matrix(1,0,0,1,0,-13.007)
    }

    27.23% {
        transform: matrix(1,0,0,1,0,-2.352)
    }

    38.34% {
        transform: matrix(1,0,0,1,0,.311)
    }

    60.56% {
        transform: matrix(1,0,0,1,0,-.007)
    }

    82.78% {
        transform: matrix(1,0,0,1,0,0)
    }

    to {
        transform: matrix(1,0,0,1,0,0)
    }
}

@keyframes proofAnimationTop {
    0% {
        transform: matrix(1,0,0,1,0,300)
    }

    4.1% {
        transform: matrix(1,0,0,1,0,125.912)
    }

    8.11% {
        transform: matrix(1,0,0,1,0,31.647)
    }

    12.11% {
        transform: matrix(1,0,0,1,0,-5.53)
    }

    16.12% {
        transform: matrix(1,0,0,1,0,-13.007)
    }

    27.23% {
        transform: matrix(1,0,0,1,0,-2.352)
    }

    38.34% {
        transform: matrix(1,0,0,1,0,.311)
    }

    60.56% {
        transform: matrix(1,0,0,1,0,-.007)
    }

    82.78% {
        transform: matrix(1,0,0,1,0,0)
    }

    to {
        transform: matrix(1,0,0,1,0,0)
    }
}

.woocommerce form .form-row .required {
    visibility: visible
}

.cff-wrapper:after {
    content: "";
    display: table;
    clear: both
}

#cff {
    float: left;
    width: 100%;
    margin: 0 auto;
    padding: 0;
    -webkit-box-sizing: border-box;
    -moz-box-sizing: border-box;
    box-sizing: border-box
}

.cff-wrapper-ctn {
    overflow: hidden;
    box-sizing: border-box
}

.cff-wrapper-ctn.cff-wrapper-fixed-height {
    overflow: auto;
    overflow-x: hidden
}

#cff .cff-masonry-posts,#cff .cff-posts-wrap,.cff-wrapper-ctn {
    position: relative;
    clear: both;
    height: 100%;
    top: 0;
    bottom: 0;
    width: 100%
}

#cff .cff-posts-wrap-box-shadow {
    padding: 5px
}

#cff .cff-item {
    float: left;
    width: 100%;
    clear: both;
    padding: 20px 0 15px;
    margin: 0;
    border-bottom: 1px solid #ddd
}

#cff .cff-item:first-child {
    padding-top: 0
}

#cff .cff-item.cff-box,#cff .cff-item.cff-box:first-child {
    padding: 15px;
    margin: 8px 0;
    background: rgb(255 255 255 / .5);
    border: none;
    -webkit-box-sizing: border-box;
    -moz-box-sizing: border-box;
    box-sizing: border-box
}

#cff .cff-item.cff-box:first-child {
    margin-top: 0
}

#cff .cff-item.cff-box:last-child {
    margin-bottom: 0
}

#cff .cff-item.cff-shadow {
    box-shadow: 0 0 10px 0 rgb(0 0 0 / .15);
    -moz-box-shadow: 0 0 10px 0 rgb(0 0 0 / .15);
    -webkit-box-shadow: 0 0 10px 0 rgb(0 0 0 / .15)
}

.cff-header {
    width: 100%;
    margin: 0 0 15px;
    padding: 0;
    line-height: 1;
    -webkit-box-sizing: border-box;
    box-sizing: border-box;
    display: flex;
    align-items: center
}

.cff-header .fa,.cff-header svg {
    margin: 0 10px 0 0;
    padding: 0
}

.cff-visual-header {
    margin-bottom: 24px!important
}

.cff-visual-header .cff-header-hero {
    width: 100%;
    height: 300px;
    position: relative;
    overflow: hidden
}

.cff-visual-header .cff-header-hero img {
    width: 100%;
    display: none
}

.cff-visual-header .cff-likes-box {
    position: absolute;
    bottom: 10px;
    right: 10px;
    padding: 5px;
    background: #eee;
    line-height: 1;
    border-radius: 2px;
    color: #445790
}

.cff-visual-header .cff-likes-box .cff-square-logo {
    float: left;
    display: inline-block;
    line-height: 0
}

.cff-visual-header .cff-likes-box .cff-square-logo svg {
    width: 18px;
    vertical-align: top
}

.cff-visual-header .cff-likes-box .cff-likes-count {
    float: left;
    display: inline-block;
    margin-left: 8px;
    vertical-align: top;
    font-size: 15px;
    line-height: 20px
}

.cff-visual-header .cff-header-inner-wrap {
    position: relative;
    display: block;
    text-decoration: none!important
}

.cff-visual-header .cff-header-inner-wrap a {
    color: inherit!important;
    border: 0
}

.cff-visual-header .cff-header-img img {
    display: block;
    width: 100px;
    border-radius: 3px;
    padding: 0;
    margin: 0
}

.cff-visual-header.cff-has-cover .cff-header-img img {
    border: 2px solid #fff
}

.cff-visual-header .cff-header-img {
    position: absolute;
    display: inline-block;
    line-height: 1
}

.cff-visual-header.cff-has-cover .cff-header-img {
    top: -25px;
    left: 10px
}

.cff-visual-header .cff-header-text {
    display: inline-block;
    float: left;
    padding-top: 10px;
    margin: 0
}

#cff .cff-visual-header .cff-header-text h3,.cff-visual-header .cff-header-text h3 {
    display: inline-block!important;
    width: auto!important;
    margin: 0 8px 0 0!important;
    padding: 0!important;
    font-size: 1.2em!important;
    line-height: 1.2em!important
}

.cff-visual-header.cff-has-name {
    min-height: 100px
}

.cff-visual-header.cff-has-cover.cff-has-name .cff-header-text {
    min-height: 75px;
    margin-left: 125px!important
}

.cff-visual-header.cff-has-name .cff-header-text {
    margin-left: 120px!important;
    padding-top: 30px
}

.cff-visual-header.cff-has-name.cff-has-about .cff-header-text,.cff-visual-header.cff-has-name.cff-has-cover .cff-header-text {
    padding-top: 10px!important
}

#cff .cff-visual-header .cff-header-inner-wrap .cff-bio,.cff-visual-header .cff-header-inner-wrap .cff-bio {
    display: block;
    width: 100%;
    clear: both;
    margin: 3px 0 0;
    padding: 0;
    line-height: 1.2em
}

.cff-visual-header .cff-header-name {
    float: left;
    padding: 0 5px 2px 0!important
}

.cff-visual-header .cff-bio-info {
    font-size: .9em;
    line-height: 1.7
}

.cff-visual-header .cff-bio-info svg {
    display: inline-block;
    width: 1em;
    vertical-align: middle;
    position: relative;
    top: -2px
}

.cff-posts-count svg {
    padding-right: 3px
}

.cff-header-inner-wrap:after,.cff-header-text:after {
    display: table;
    clear: both;
    content: " "
}

#cff .cff-author-img.cff-no-consent img,#cff .cff-expand,#cff .cff-less {
    display: none
}

#cff.cff-default-styles .cff-author a,#cff.cff-default-styles .cff-credit a,#cff.cff-default-styles a {
    text-decoration: none
}

#cff.cff-default-styles a:focus,#cff.cff-default-styles a:hover {
    text-decoration: underline
}

#cff .cff-post-text-link {
    display: block
}

.cff-post-text {
    width: 100%;
    float: left
}

#cff .cff-post-desc,#cff h3,#cff h4,#cff h5,#cff h6,#cff p {
    float: left;
