:root {
    --global-palette1: #3c84c5;
    --global-palette2: #ee3127;
    --global-palette3: #000000;
    --global-palette4: #2D3748;
    --global-palette5: #4A5568;
    --global-palette6: #718096;
    --global-palette7: #f4f4f4;
    --global-palette8: #F7FAFC;
    --global-palette9: #ffffff;
    --global-palette9rgb: 255, 255, 255;
    --global-palette-highlight: var(--global-palette1);
    --global-palette-highlight-alt: var(--global-palette4);
    --global-palette-highlight-alt2: var(--global-palette9);
    --global-palette-btn-bg: var(--global-palette1);
    --global-palette-btn-bg-hover: #47423f;
    --global-palette-btn: var(--global-palette9);
    --global-palette-btn-hover: var(--global-palette9);
    --global-body-font-family: Lato, sans-serif;
    --global-heading-font-family: Lato, sans-serif;
    --global-primary-nav-font-family: inherit;
    --global-fallback-font: sans-serif;
    --global-display-fallback-font: sans-serif;
    --global-content-width: 1490px;
    --global-content-wide-width: calc(1490px + 230px);
    --global-content-narrow-width: 1210px;
    --global-content-edge-padding: 0.09rem;
    --global-content-boxed-padding: 0.27rem;
    --global-calc-content-width: calc(1490px - var(--global-content-edge-padding) - var(--global-content-edge-padding) );
    --wp--style--global--content-size: var(--global-calc-content-width)
}

.wp-site-blocks {
    --global-vw: calc( 100vw - ( 0.5 * var(--scrollbar-offset)))
}

body {
    background: var(--global-palette7)
}

body,input,select,optgroup,textarea {
    font-style: normal;
    font-weight: 400;
    font-size: 17px;
    line-height: 1.6;
    font-family: var(--global-body-font-family);
