}

.is-large-text {
    font-size: 2.25em
}

.is-larger-text {
    font-size: 3em
}

.has-drop-cap:not(:focus):first-letter {
    float: left;
    font-size: 8.4em;
    font-style: normal;
    font-weight: 100;
    line-height: .68;
    margin: .05em .1em 0 0;
    text-transform: uppercase
}

body.rtl .has-drop-cap:not(:focus):first-letter {
    float: none;
    margin-left: .1em
}

p.has-drop-cap.has-background {
    overflow: hidden
}

:root :where(p.has-background) {
    padding: 1.25em 2.375em
}

:where(p.has-text-color:not(.has-link-color)) a {
    color: inherit
}

p.has-text-align-left[style*="writing-mode:vertical-lr"],p.has-text-align-right[style*="writing-mode:vertical-rl"] {
    rotate: 180deg
}

@keyframes rotate-forever {
    0% {
        transform: rotate(0deg)
    }

    to {
        transform: rotate(1turn)
    }
}

@keyframes spinner-loader {
    0% {
        transform: rotate(0deg)
    }

    to {
        transform: rotate(1turn)
    }
}

.pum-container,.pum-content,.pum-content+.pum-close,.pum-content+.pum-close:active,.pum-content+.pum-close:focus,.pum-content+.pum-close:hover,.pum-overlay,.pum-title {
    background: none;
    border: none;
    bottom: auto;
    clear: none;
    cursor: default;
    float: none;
    font-family: inherit;
    font-size: medium;
    font-style: normal;
    font-weight: 400;
    height: auto;
    left: auto;
    letter-spacing: normal;
    line-height: normal;
    max-height: none;
    max-width: none;
    min-height: 0;
    min-width: 0;
    overflow: visible;
    position: static;
    right: auto;
    text-align: left;
    text-decoration: none;
    text-indent: 0;
    text-transform: none;
    top: auto;
    visibility: visible;
    white-space: normal;
    width: auto;
    z-index: auto
}

.pum-content,.pum-title {
    position: relative;
    z-index: 1
}

.pum-overlay {
    bottom: 0;
    display: none;
    height: 100%;
    left: 0;
    overflow: auto;
    overflow: initial;
    position: fixed;
    right: 0;
    top: 0;
    transition: all .15s ease-in-out;
    width: 100%;
    z-index: 1999999999
}

.pum-overlay.pum-form-submission-detected,.pum-overlay.pum-preview {
    display: block
}

.pum-overlay,.pum-overlay *,.pum-overlay :after,.pum-overlay :before,.pum-overlay:after,.pum-overlay:before {
    box-sizing: border-box
}

.pum-container {
    margin-bottom: 3em;
    position: absolute;
    top: 100px;
    z-index: 1999999999
}

.pum-container.pum-responsive {
    height: auto;
    left: 50%;
    margin-left: -47.5%;
    overflow: visible;
    width: 95%
}

.pum-container.pum-responsive img {
    height: auto;
    max-width: 100%
}

@media only screen and (min-width: 1024px) {
    .pum-container.pum-responsive.pum-responsive-nano {
        margin-left:-5%;
        width: 10%
    }

    .pum-container.pum-responsive.pum-responsive-micro {
        margin-left: -10%;
        width: 20%
    }

    .pum-container.pum-responsive.pum-responsive-tiny {
        margin-left: -15%;
        width: 30%
    }

    .pum-container.pum-responsive.pum-responsive-small {
        margin-left: -20%;
        width: 40%
    }

    .pum-container.pum-responsive.pum-responsive-medium {
        margin-left: -30%;
        width: 60%
    }

    .pum-container.pum-responsive.pum-responsive-normal {
        margin-left: -30%;
        width: 70%
    }

    .pum-container.pum-responsive.pum-responsive-large {
        margin-left: -35%;
        width: 80%
    }

    .pum-container.pum-responsive.pum-responsive-xlarge {
        margin-left: -47.5%;
        width: 95%
    }

    .pum-container.pum-responsive.pum-position-fixed {
        position: fixed
    }
}

@media only screen and (max-width: 1024px) {
    .pum-container.pum-responsive.pum-position-fixed {
        position:absolute
    }
}

.pum-container.custom-position {
    left: auto;
    margin-left: inherit;
    top: auto
}

.pum-container .pum-title {
    margin-bottom: .5em
}

.pum-container .pum-content:focus {
    outline: none
}

.pum-container .pum-content>:first-child {
    margin-top: 0
}

.pum-container .pum-content>:last-child {
    margin-bottom: 0
}

.pum-container .pum-content+.pum-close {
    background-color: #0000;
    cursor: pointer;
    line-height: 1;
    min-width: 1em;
    position: absolute;
    text-align: center;
    text-decoration: none;
    z-index: 2
}

.pum-container .pum-content+.pum-close>span {
    position: relative;
    z-index: 1
}

.pum-container.pum-scrollable .pum-content {
    max-height: 95%;
    overflow: auto;
    overflow-y: scroll
}

.pum-overlay.pum-overlay-disabled {
    visibility: hidden
}

.pum-overlay.pum-overlay-disabled::-webkit-scrollbar {
    display: block
}

.pum-overlay.pum-overlay-disabled .pum-container {
    visibility: visible
}

.pum-overlay.pum-click-to-close {
    cursor: pointer
}

html.pum-open.pum-open-overlay,html.pum-open.pum-open-overlay.pum-open-fixed .pum-overlay {
    overflow: hidden
}

html.pum-open.pum-open-overlay.pum-open-fixed .pum-container {
    position: fixed
}

html.pum-open.pum-open-overlay.pum-open-scrollable body>:not([aria-modal=true]) {
    padding-right: 15px
}

html.pum-open.pum-open-overlay.pum-open-scrollable .pum-overlay.pum-active {
    overflow-y: scroll;
    -webkit-overflow-scrolling: touch
}

html.pum-open.pum-open-overlay-disabled.pum-open-fixed .pum-container {
    position: fixed
}

html.pum-open.pum-open-overlay-disabled.pum-open-scrollable .pum-overlay.pum-active {
    height: auto;
    position: static;
    width: auto
}

.pum-cta-wrapper {
    display: inline-block;
    max-width: 100%;
    width: auto
}

.pum-cta-wrapper.alignleft {
    display: block;
    text-align: left
}

.pum-cta-wrapper.aligncenter {
    display: block;
    text-align: center
}

.pum-cta-wrapper.alignright {
    display: block;
    text-align: right
}

.pum-cta-wrapper.alignfull {
    display: block;
    width: 100%
}

.pum-cta-wrapper.alignfull .pum-cta {
    width: 100%
}

.pum-cta-wrapper .pum-cta {
    border-radius: 9999px;
    box-sizing: border-box;
    cursor: pointer;
    display: inline-block;
    font-family: inherit;
    font-size: inherit;
    line-height: inherit;
    padding: 1rem 2.25rem;
    text-align: center;
    text-decoration: none;
    transition: filter .15s ease-in-out,background-color .15s ease-in-out;
    width: auto
}

.pum-cta-wrapper:not(.is-style-outline):not(.is-style-text-only) .pum-cta {
    background-color: var(--wp--preset--color--contrast,#000);
    border: none;
    color: var(--wp--preset--color--base,#fff)
}

.pum-cta-wrapper:not(.is-style-outline):not(.is-style-text-only) .pum-cta:hover {
    filter: brightness(.85)
}

.pum-cta-wrapper.is-style-outline .pum-cta {
    background-color: #0000;
    border: 1px solid;
    color: var(--wp--preset--color--contrast,currentcolor);
    padding: calc(1rem - 1px) calc(2.25rem - 1px)
}

.pum-cta-wrapper.is-style-outline .pum-cta:hover {
    background-color: #0000000d;
    filter: brightness(1.05)
}

.pum-cta-wrapper.is-style-text-only .pum-cta {
    background-color: #0000;
    border: none;
    color: var(--wp--preset--color--contrast,currentcolor);
    padding: .5rem 1rem
}

.pum-cta-wrapper.is-style-text-only .pum-cta:hover {
    text-decoration: underline
}

@supports not (color: var(--wp--preset--color--contrast)) {
    .pum-cta-wrapper:not(.is-style-outline):not(.is-style-text-only) .pum-cta {
        background-color:#1e1e1e;
        color: #fff
    }

    .pum-cta-wrapper.is-style-outline .pum-cta,.pum-cta-wrapper.is-style-text-only .pum-cta {
        color: inherit
    }
}

.pum-form {
